        float cs=cos(uvTransform.z),sn=sin(uvTransform.z);
        uv=float2(cs*uv.x-sn*uv.y,sn*uv.x+cs*uv.y)*uvSettings.xy+uvTransform.xy+.5;
        float3 albedo=pow(max(baseColor.rgb,.0001),2.2);
        float rough=clamp(material.y,.045,1),metal=saturate(material.x),ao=saturate(material.w);
        float alpha=baseColor.a;
        if(textureFlags.x>.5) {
            float4 texel=sampleMap(baseMap,uv);
            if(mapChannels.x>.5)texel.rgb=channelValue(texel,mapChannels.x).xxx;
            albedo*=lerp(1,pow(max(texel.rgb,.0001),2.2),mapStrengths.x);alpha*=lerp(1,texel.a,mapStrengths.x);
        }
        if(textureFlags.y>.5)rough=clamp(lerp(rough,channelValue(sampleMap(roughMap,uv),mapChannels.y),mapStrengths.y),.045,1);
        if(textureFlags.z>.5)metal=saturate(lerp(metal,channelValue(sampleMap(metalMap,uv),mapChannels.z),mapStrengths.z));
